// Chụp ảnh dù lượn tại điểm cất cánh (ngày/đêm), màn chọn phương tiện (chooser.png) và giao diện khi bay (flying-ui.png) vào tests/screens/explore/ (không commit).
//   npm run build && node tests/explore-shots.mjs
import { fileURLToPath } from 'node:url';
import { mkdirSync } from 'node:fs';
import { serveDir, launch, openApp, frames } from './lib.mjs';

const out = fileURLToPath(new URL('./screens/explore/', import.meta.url));
mkdirSync(out, { recursive: true });
const srv = await serveDir(fileURLToPath(new URL('../dist/', import.meta.url)));
const browser = await launch();
try {
  const P = await openApp(browser, srv.url, { width: 960, height: 600 });
  await P.page.addStyleTag({ content: 'body > *:not(canvas) { visibility: hidden !important; }' });   // ẩn giao diện để thấy cảnh
  await P.page.evaluate(() => {
    const { exCreate, exBuildGlider, exPlaceGlider, exChase } = window.__app.exFlight;
    const { THREE, scene, camera, controls } = window.__app;
    const s = exCreate(), g = exBuildGlider(), tgt = new THREE.Vector3();
    scene.add(g); exPlaceGlider(g, s); exChase(camera, tgt, s, 1 / 60, true);
    controls.target.copy(tgt); controls.update();
    window.__shot = () => { exPlaceGlider(g, s); exChase(camera, tgt, s, 1 / 60, true); controls.target.copy(tgt); controls.update(); };
  });
  for (const [name, night] of [['takeoff-ngay', 0], ['takeoff-dem', 1]]) {
    await P.page.evaluate((v) => { window.__app.dayNight.target = v; window.__app.dayNight.night = v; }, night);
    await frames(P.page, 4);
    await P.page.evaluate(() => window.__shot());
    await frames(P.page, 3);
    await P.page.screenshot({ path: out + name + '.png' });
    console.log('đã chụp', name);
  }
  await P.page.close();   // SwiftShader chậm: đóng trang đang vẽ để trang sau còn CPU
  // Màn chọn và giao diện khi bay (giữ nguyên giao diện, không ẩn panel)
  const C = await openApp(browser, srv.url + '?chooser', { width: 960, height: 600 });
  await C.page.waitForSelector('#chooser', { state: 'visible', timeout: 240000 });
  await frames(C.page, 2);
  await C.page.screenshot({ path: out + 'chooser.png' }); console.log('đã chụp chooser');
  await C.page.close();
  const F = await openApp(browser, srv.url + '?explore=glider', { width: 960, height: 600 });
  await frames(F.page, 6);
  await F.page.screenshot({ path: out + 'flying-ui.png' }); console.log('đã chụp flying-ui');
  if (P.errors.length) console.log(P.errors.join('\n'));
} finally { await browser.close(); srv.close(); }
// Tiện ích chung cho các script kiểm tra: server tĩnh + mở trang bằng Chromium (Playwright).
import { fileURLToPath } from 'node:url';
import http from 'node:http';
import fs from 'node:fs';
import path from 'node:path';
import { chromium } from 'playwright';

const THREE_DIR = fileURLToPath(new URL('../node_modules/three/', import.meta.url));
const TYPES = { '.html': 'text/html; charset=utf-8', '.js': 'text/javascript', '.mjs': 'text/javascript', '.css': 'text/css', '.json': 'application/json', '.svg': 'image/svg+xml', '.mp3': 'audio/mpeg', '.png': 'image/png' };

/** Server tĩnh tối giản cho một thư mục (theo symlink). Trả về { url, close }. */
export function serveDir(dir) {
  const root = path.resolve(process.env.TEST_DIST || dir);   // TEST_DIST=<dist khac>: chay nguyen mot test tren ban build khac (vd. main) de biet loi co tu truoc khong
  const server = http.createServer((req, res) => {
    let p = decodeURIComponent(new URL(req.url, 'http://x').pathname);
    if (p.endsWith('/')) p += 'index.html';
    let file = path.join(root, p);
    if (!file.startsWith(root)) { res.writeHead(403); return res.end(); }
    // Bản gốc nạp three từ /three/… : nếu thư mục không có thì lấy từ node_modules/three của project
    if (p.startsWith('/three/') && !fs.existsSync(file)) file = path.join(THREE_DIR, p.slice('/three/'.length));
    fs.readFile(file, (err, data) => {
      if (err) { res.writeHead(404); return res.end('not found'); }
      res.writeHead(200, { 'content-type': TYPES[path.extname(file)] || 'application/octet-stream' });
      res.end(data);
    });
  });
  return new Promise((ok) => server.listen(0, '127.0.0.1', () => ok({ url: `http://127.0.0.1:${server.address().port}/`, close: () => server.close() })));
}

export async function launch() {
  if (process.env.TEST_REAL_GPU) return chromium.launch({ executablePath: process.env.CHROMIUM_PATH || undefined, args: [...(process.platform === 'win32' ? ['--use-angle=d3d11'] : []), '--ignore-gpu-blocklist', '--enable-gpu'] });   // TEST_REAL_GPU=1: GPU that, chi de chan doan nhanh; ket qua chinh thuc van la SwiftShader
  return chromium.launch({
    executablePath: process.env.CHROMIUM_PATH || undefined,
    args: ['--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--ignore-gpu-blocklist']
  });
}

/** Mở trang với ?test, chặn font Google (không cần cho kiểm tra), chờ khung hình đầu.
    before(page): chạy trước khi mở trang (gắn route / lắng nghe yêu cầu, console từ lúc đầu). */
export async function openApp(browser, url, { width = 480, height = 270, mobile = false, before = null } = {}) {
  const page = await browser.newPage(mobile ? { viewport: { width, height }, isMobile: true, hasTouch: true, deviceScaleFactor: 2 } : { viewport: { width, height } });
  const errors = []; page.setDefaultTimeout(240000);
  if (before) await before(page);
  page.on('pageerror', (e) => errors.push(String(e)));
  page.on('console', (m) => { if (m.type() === 'error' && !/fonts\.(googleapis|gstatic)|ERR_FAILED|net::/.test(m.text())) errors.push(m.text()); });
  await page.route(/fonts\.(googleapis|gstatic)\.com/, (r) => r.abort());
  await page.goto(url + (url.includes('?') ? '&' : '?') + 'test', { waitUntil: 'load', timeout: 180000 });
  await page.waitForFunction(() => window.__app && document.getElementById('loading')?.classList.contains('done'), null, { timeout: 180000 });
  return { page, errors };
}

/** Chờ n khung hình. */
export const frames = (page, n = 2) => page.evaluate((n) => new Promise((ok) => { let i = 0; const f = () => (++i >= n ? ok() : requestAnimationFrame(f)); requestAnimationFrame(f); }), n);

/** Chờ hiệu ứng bay camera (flyTo) kết thúc. */
// Phần mềm dựng hình (SwiftShader) rất chậm nên tua nhanh: đẩy tiến độ bay gần tới đích để khung hình kế tiếp hoàn tất.
export async function waitFlight(page) {
  await page.evaluate(() => { const f = window.__app.cam.flight; if (window.__app.cam.mode === 'fly') f.t = Math.max(f.t, 0.999); });
  await page.waitForFunction(() => window.__app.cam.mode !== 'fly', null, { timeout: 240000 });
}
